using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Media;
using System.Windows.Media.Imaging;

namespace DriftStart;
public sealed class JudgeHud:Window
{
 readonly TextBlock title=new(){FontSize=17,FontWeight=FontWeights.Bold,TextTrimming=TextTrimming.CharacterEllipsis};readonly TextBlock meta=new(){Foreground=Paint.Brush("#929297"),FontSize=9,TextTrimming=TextTrimming.CharacterEllipsis};readonly TextBlock total=new(){FontSize=12,FontWeight=FontWeights.Black,Foreground=Paint.Brush("#F20D4F"),TextAlignment=TextAlignment.Right};readonly TextBox score1=new(){Width=48,Height=28,MaxLength=6,Padding=new(5,3,5,3)};readonly TextBox score2=new(){Width=48,Height=28,MaxLength=6,Padding=new(5,3,5,3)};readonly StackPanel photos=new(){Orientation=Orientation.Horizontal,Visibility=Visibility.Collapsed};readonly StackPanel pairSelectors=new(){Orientation=Orientation.Horizontal};Entry? active,pairA,pairB;Match? pairMatch;string? activeDiscipline;
 public event Action<Entry,int,double,string?>? ScoreSubmitted;
 public event Action<string,Entry,int,double,string?>? PairScoreSubmitted;
 public event Action<int>? NavigateRequested;
 public JudgeHud(){Title="DriftStart Judge HUD";WindowStyle=WindowStyle.None;AllowsTransparency=true;Background=Brushes.Transparent;Topmost=true;ShowInTaskbar=false;Width=540;Height=142;var box=new Border{Background=Paint.Brush("#ED09090B"),BorderBrush=Paint.Brush("#F20D4F"),BorderThickness=new(2),CornerRadius=new(18,3,18,3),Padding=new(15,9,13,9)};var root=new Grid();root.RowDefinitions.Add(new(){Height=GridLength.Auto});root.RowDefinitions.Add(new(){Height=new(1,GridUnitType.Star)});var head=new Grid();head.Children.Add(new TextBlock{Text="DRIFTSTART / JUDGE",Foreground=Paint.Brush("#F20D4F"),FontSize=9,FontWeight=FontWeights.Bold});var close=new Button{Content="×",Width=24,Height=20,Padding=new(0),HorizontalAlignment=HorizontalAlignment.Right};close.Click+=(_,_)=>Hide();head.Children.Add(close);root.Children.Add(head);var row=new Grid{Margin=new(0,7,0,0)};row.ColumnDefinitions.Add(new(){Width=new(1,GridUnitType.Star)});row.ColumnDefinitions.Add(new(){Width=GridLength.Auto});Grid.SetRow(row,1);var info=new StackPanel();info.Children.Add(title);info.Children.Add(meta);info.Children.Add(pairSelectors);row.Children.Add(info);var control=new StackPanel{Orientation=Orientation.Horizontal,VerticalAlignment=VerticalAlignment.Center};control.Children.Add(score1);var save1=new Button{Content="P1",Margin=new(4,0,8,0),Padding=new(7,4,7,4),FontSize=9};save1.Click+=(_,_)=>Submit(0,score1.Text);control.Children.Add(save1);control.Children.Add(score2);var save2=new Button{Content="P2",Margin=new(4,0,8,0),Padding=new(7,4,7,4),FontSize=9};save2.Click+=(_,_)=>Submit(1,score2.Text);control.Children.Add(save2);control.Children.Add(total);Grid.SetColumn(control,1);row.Children.Add(control);root.Children.Add(row);box.Child=root;Content=box;Left=SystemParameters.PrimaryScreenWidth-Width-28;Top=28;head.MouseLeftButtonDown+=(_,e)=>{if(e.LeftButton==MouseButtonState.Pressed)DragMove();};}
 void Submit(int attempt,string value){double maximum=activeDiscipline switch{"trajectory"=>40,"angle"=>35,"style"=>25,_=>100};if(active==null||!double.TryParse(value.Replace(',','.'),System.Globalization.NumberStyles.AllowDecimalPoint,System.Globalization.CultureInfo.InvariantCulture,out var score)||score<0||score>maximum){MessageBox.Show($"Допустимая оценка: от 0 до {maximum:0}.","Оценка",MessageBoxButton.OK,MessageBoxImage.Warning);return;}if(pairMatch!=null)PairScoreSubmitted?.Invoke(pairMatch.Id,active,attempt,score,activeDiscipline);else ScoreSubmitted?.Invoke(active,attempt,score,activeDiscipline);}
 static Image? Photo(Entry p){if(p.VehicleImage==null)return null;try{return new Image{Width=80,Height=45,Stretch=Stretch.Uniform,Source=new BitmapImage(new Uri(p.VehicleImage)),Margin=new(0,5,8,0)};}catch{return null;}}
 public void Display(Entry p,string? discipline=null){pairMatch=null;pairA=pairB=null;active=p;activeDiscipline=discipline;pairSelectors.Children.Clear();var previous=new Button{Content="← ПРЕДЫДУЩИЙ",Padding=new(8,3,8,3),Margin=new(0,5,6,4)};previous.Click+=(_,_)=>NavigateRequested?.Invoke(-1);pairSelectors.Children.Add(previous);var next=new Button{Content="СЛЕДУЮЩИЙ →",Padding=new(8,3,8,3),Margin=new(0,5,6,4)};next.Click+=(_,_)=>NavigateRequested?.Invoke(1);pairSelectors.Children.Add(next);pairSelectors.Visibility=Visibility.Visible;photos.Children.Clear();if(Photo(p)is Image image)photos.Children.Add(image);title.Text="▶  "+p.Name;double maximum=discipline switch{"trajectory"=>40,"angle"=>35,"style"=>25,_=>100};string disciplineName=Account.DisciplineLabel(discipline).ToUpperInvariant();meta.Text=$"АКТИВНЫЙ ПИЛОТ  ·  #{p.StaticId??"—"}  ·  {p.VehicleName??"МАШИНА НЕ УКАЗАНА"}  ·  ПОЛЯ: {disciplineName} 0–{maximum:0}";double first=p.Scores.ElementAtOrDefault(0)??0,second=p.Scores.ElementAtOrDefault(1)??0;total.Text=$"ИТОГ P1 {first:0.##}\nИТОГ P2 {second:0.##}  ·  BEST {Math.Max(first,second):0.##}";score1.ToolTip=$"{disciplineName} · попытка 1";score2.ToolTip=$"{disciplineName} · попытка 2";score1.Text=discipline==null?"":p.DisciplineScores?.ElementAtOrDefault(0)?.GetValueOrDefault(discipline).ToString("0.##")??"";score2.Text=discipline==null?"":p.DisciplineScores?.ElementAtOrDefault(1)?.GetValueOrDefault(discipline).ToString("0.##")??"";if(!IsVisible)Show();}
 public void DisplayPair(Entry a,Entry b,Match match,string? discipline=null){pairA=a;pairB=b;pairMatch=match;activeDiscipline=discipline;pairSelectors.Children.Clear();foreach(var p in new[]{a,b}){var selected=p;var button=new Button{Content=p.Name,Padding=new(9,4,9,4),Margin=new(0,5,6,4)};button.Click+=(_,_)=>SelectPairPilot(selected);pairSelectors.Children.Add(button);}pairSelectors.Visibility=Visibility.Visible;photos.Children.Clear();if(Photo(a)is Image ia)photos.Children.Add(ia);if(Photo(b)is Image ib)photos.Children.Add(ib);SelectPairPilot(active?.Id==b.Id?b:a);if(!IsVisible)Show();}
 void SelectPairPilot(Entry p){if(pairMatch==null||pairA==null||pairB==null)return;active=p;bool isA=p.Id==pairA.Id;title.Text="▶  "+p.Name;meta.Text=$"{Account.DisciplineLabel(activeDiscipline).ToUpperInvariant()}  ·  ПРОЕЗД 1: {(isA?"ЛИДЕР":"ВЕДОМЫЙ")}  ·  ПРОЕЗД 2: {(isA?"ВЕДОМЫЙ":"ЛИДЕР")}";score1.Text=activeDiscipline==null?"":pairMatch.TandemDisciplineScores?.ElementAtOrDefault(0)?.GetValueOrDefault(p.Id)?.GetValueOrDefault(activeDiscipline).ToString("0.##")??"";score2.Text=activeDiscipline==null?"":pairMatch.TandemDisciplineScores?.ElementAtOrDefault(1)?.GetValueOrDefault(p.Id)?.GetValueOrDefault(activeDiscipline).ToString("0.##")??"";double first=pairMatch.TandemScores?.ElementAtOrDefault(0)?.GetValueOrDefault(p.Id)??0,second=pairMatch.TandemScores?.ElementAtOrDefault(1)?.GetValueOrDefault(p.Id)??0;total.Text=$"ИТОГ P1 {first:0.##}\nИТОГ P2 {second:0.##}  ·  BEST {Math.Max(first,second):0.##}";}
 protected override void OnContentRendered(EventArgs e){base.OnContentRendered(e);if(Content is Border box){box.CornerRadius=new(18,3,18,3);box.BorderThickness=new(2);}}
}
